use std::fs;
use std::io;

pub fn list(root: &str) -> Result<Vec<(i32, String)>, io::Error> {
    let mut files = Vec::new();
    for item in fs::read_dir(root)? {
        let entry = item?;
        if !entry.file_type()?.is_file() {
            continue;
        }
        let name = entry.file_name().to_string_lossy().into_owned();
        if name.len() != 13 || !name.starts_with('d') || !name.ends_with(".tbl") {
            continue;
        }
        let digits = &name[1..9];
        if !digits.bytes().all(|c| c.is_ascii_digit()) {
            continue;
        }
        if let Ok(day) = digits.parse::<i32>() {
            files.push((day, entry.path().to_string_lossy().into_owned()));
        }
    }
    files.sort_by_key(|x| x.0);
    Ok(files)
}

pub fn read_rows(path: &str) -> Result<(String, i32), io::Error> {
    let text = fs::read_to_string(path)?;
    let rows = text.lines().filter(|line| !line.trim().is_empty()).count() as i32;
    Ok((text, rows))
}
