use std::fs;

pub fn soak(files: &[(i32, String)], root: &str) -> Result<(), i32> {
    let _ = fs::remove_dir_all(root);
    fs::create_dir_all(root).map_err(|_| 1)?;
    let mut ordered = files.to_vec();
    ordered.sort_by_key(|x| x.0);
    for (day, source) in ordered {
        let name = format!("d{:08}.tbl", day);
        fs::copy(source, format!("{}/{}", root, name)).map_err(|_| 1)?;
    }
    Ok(())
}
