#[path = "../hopcue/rim.rs"]
mod rim;
#[path = "../restpit/soak.rs"]
mod soak;
#[path = "../shardfold/read.rs"]
mod read;

use std::fs;

fn reset_publication() {
    let _ = fs::remove_dir_all("/app/packbay/stage");
    let _ = fs::remove_dir_all("/app/packbay/latest");
    let _ = fs::create_dir_all("/app/packbay/stage");
    let _ = fs::create_dir_all("/app/packbay/latest");
}

pub fn fold() -> Result<(Vec<(i32, String)>, i32), i32> {
    let wall: i32 = fs::read_to_string("/app/opstext/WALL")
        .map_err(|_| 1)?.trim().parse().map_err(|_| 1)?;
    let listed = read::list("/app/daywell").map_err(|_| 1)?;
    let picked = rim::rim(wall, listed);
    reset_publication();
    if picked.is_empty() {
        return Err(1);
    }

    let mut packed = Vec::new();
    let mut taken = 0i32;
    for (day, source) in picked {
        let (_, rows) = read::read_rows(&source).map_err(|_| 1)?;
        let destination = format!("/app/packbay/stage/d{:08}.tbl", day);
        fs::copy(&source, &destination).map_err(|_| 1)?;
        taken = taken.checked_add(rows).ok_or(1)?;
        packed.push((day, destination));
    }
    if taken == 0 {
        reset_publication();
        return Err(1);
    }

