    let output = template
        .replace("__P__", probe)
        .replace("__M__", &matched.to_string())
        .replace("__T__", &taken.to_string());
    fs::create_dir_all("/app/bloturn").map_err(|_| 1)?;
    fs::write("/app/bloturn/check.json", output).map_err(|_| 1)
}

pub fn gait(taken: i32, packed: &[(i32, String)]) -> i32 {
    let _ = fs::remove_file("/app/bloturn/GUARD");
    if packed.is_empty() || taken <= 0 {
        return 1;
    }

    let mut matched = 0i32;
    let mut live_probe: Option<String> = None;
    for (day, staged_path) in packed {
        let name = format!("d{:08}.tbl", day);
        let source_path = format!("/app/daywell/{}", name);
        let latest_path = format!("/app/packbay/latest/{}", name);

        // These reads are deliberately independent of ledger.json and prove that
        // check generation observed the live calendar files.
        let source = match fs::read_to_string(&source_path) {
            Ok(value) => value,
            Err(_) => return 1,
        };
        let staged = match fs::read_to_string(staged_path) {
            Ok(value) => value,
            Err(_) => return 1,
        };
        let latest = match fs::read_to_string(&latest_path) {
            Ok(value) => value,
            Err(_) => return 1,
        };
        if source != staged || source != latest {
            return 1;
        }
        let count = rows(&source);
        matched = match matched.checked_add(count) {
            Some(value) => value,
            None => return 1,
        };
        if count > 0 {
            live_probe = Some(format!("{}:{}", name, count));
        }
    }

    if matched != taken {
        return 1;
    }
    let probe = match live_probe {
        Some(value) => value,
        None => return 1,
    };
    if emit(&probe, matched, taken).is_err() {
        return 1;
    }
    if fs::write("/app/bloturn/GUARD", "ok").is_err() {
        return 1;
    }
    0
}
